  ('sestriere-italy', '02F', 'Sestriere', 'Italy', 'Italy''s highest town', 'live', 'verified', 'northernLights', 'Italian Alps', '{"ski","family","culture","hiking","golf"}', '{}', '{"essential","comfort","premier","ultra"}', null, 'emerging', '{"key_facts":["Highest municipality in Italy at 2,035 m (Val Susa/Val Chisone pass, Metropolitan City of Turin); ~929 residents, ~20,000 in ski season","Hub of the cross-border Vialattea (Milky Way): 400 km of pistes, 70 lifts, 1,538-2,789 m; 96 km easy / 220 km intermediate / 84 km difficult; links to Montgenevre, France","Built in the 1930s by Giovanni Agnelli (FIAT); the twin cylindrical hotel towers are the village''s founding buildings + symbol; one was part of the 2006 Olympic Village","2006 Turin Winter Olympics: staged all men''s alpine skiing + one of three Olympic Villages; 10 alpine events 12-25 Feb 2006; 287 athletes from 60 nations","Gianni Agnelli World Cup/Olympic slope + floodlit night skiing; ~146 pistes, ~120 with snowmaking; hosted 1997 FIS Alpine World Championships","Still a live World Cup stage: two women''s giant slaloms Feb 2025, both won by Federica Brignone; skiresort.info rates the domain 4.2/5 (outstanding)","Golf Club Sestrieres: 18-hole par-65 course at 2,035 m, one of Europe''s highest; first nine built by Edoardo Agnelli in 1932","2026 = 20th anniversary of Turin 2006; competition runs still used for FIS World Cup events"],"safety":{"emergency":"112 (single European emergency, Italy unified — police/ambulance/fire/mountain rescue); legacy 118 medical / 115 fire / 113 police; Soccorso Alpino via 112","hospital":"Ospedale Edoardo Agnelli, Pinerolo (~35 km, ASL TO3, Pronto Soccorso); trauma transfer to Turin, often by helicopter","advisory_level":"L2","malaria":"none","yellow_fever":"not required","activity_note":"High-alpine winter sports: off-piste avalanche risk (ARPA Piemonte bollettino valanghe, European 5-level AINEVA scale; transceiver/shovel/probe + guide), cold, altitude (base 2,035 m, lifts 2,789 m); rescue via 112"},"timing":{"peak":"High winter — Christmas/New Year, Feb settimana bianca half-terms, Easter; highest rates + min-stay","shoulder":"Early Dec (season open, snow-sure high base) + late-season Mar-Apr spring skiing","green":"Between seasons May-Jun + Oct-Nov (lowest rates, limited opening); Jul-Sep separate golf/hiking green season","booking_lead":"Christmas/NY + Feb white weeks + World Cup weekends 3-6 mo; regular winter 1-3 mo; summer 1-2 mo","off_season_specials":"Summer golf (one of Europe''s highest) + hiking/e-bike (Jul-Sep); spring-ski value (late Mar-Apr); Turin 2006 20th-anniversary heritage breaks","event_peaks":"Ski holidays (Dec-Apr), Feb settimana bianca, FIS World Cup weekends (verify), Easter skiing, summer golf","campaign_start":"Next winter + Feb white weeks by late summer; summer golf/hiking from spring; spring-ski + Turin-2006-20th anniversary across 2025/26"},"jewels":[{"name":"Ski the whole Milky Way on one pass — ~400 km cross-border","si_tag":"Winter/Ski","status":"live","tier":"essential","price_band":"lift ~EUR 55-66/day; private instructor ~EUR 200-350/day (approx)","timing":"ski ~Dec-Apr; verify","commission_path":"school/operator 10-15%","draw_rank":1,"hook":"link Sestriere, Sauze d''Oulx, San Sicario, Claviere and French Montgenèvre across 400 km of mostly intermediate pistes on a single Vialattea ticket","si":"ski","blurb":"link Sestriere, Sauze d''Oulx, San Sicario, Claviere and French Montgenèvre across 400 km of mostly intermediate pistes on a single Vialattea ticket","when":"ski ~Dec-Apr; verify","commission":"school/operator 10-15%"},{"name":"Ski the Gianni Agnelli Olympic slope","si_tag":"Winter/Ski","status":"live","tier":"comfort","price_band":"~EUR 55-66/day lift (approx)","timing":"High winter — Christmas/New Year, Feb settimana bianca half-terms, Easter","commission_path":"school/operator 10-15%","draw_rank":2,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"