  ('petra-jordan', '04A', 'Petra', 'Jordan', 'The rose-red city carved from stone', 'live', 'verified', 'desertDunes', 'Jordan & the Levant', '{"culture","deepdive","hiking","ultra"}', '{}', '{"essential","comfort","ultra"}', null, 'anchor', '{"key_facts":["A New7Wonder of the World (2007) and UNESCO World Heritage since 1985 - the rose-red Nabataean caravan city","Entered through the Siq gorge to Al-Khazneh (the Treasury), a ~40 m carved facade; plus the Monastery (Ad-Deir) and Petra by Night","582,550 visitors in 2025 (+27% YoY) - a resilient rebound after the 2024 regional downturn (PDTRA)","The Jordan Pass covers Petra entry (1-3 days) + 40+ sites and waives the tourist-visa fee if you stay >=3 nights","US Level 3 Reconsider Travel (escalated March 2026); the Level-4 Do-Not-Travel areas are the Syria/Iraq border strips - Petra is in the south, far from them","Best season March-April & October-November; summer hits ~40C, winter is cold with rain"],"safety":{"emergency":"911 (unified - police / ambulance / civil defense); Tourist Police +962 79 550 5755","hospital":"Wadi Musa clinics + Amman for major referral; carry travel-medical + evac insurance","advisory_level":"L3","activity_note":"L3 Reconsider Travel - disclose prominently. Level-4 areas = Syria/Iraq borders (far north/east); Petra is in the south, far from them. Steep trail (Monastery ~800 steps) + summer heat (~40C) care; carry water; guide for back routes."},"timing":{"peak":"Mar-Apr & Oct-Nov (clear light, comfortable days); Apr/May/Sep/Oct heaviest crowds","shoulder":"Mar + Nov","green":"Jun-Aug (~40C, early-morning touring, value) + Dec-Feb (cold, rain, possible snow)","booking_lead":"Petra by Night + nearby camps constrained in peak - book well ahead; Jordan Pass online before arrival for visa waiver","off_season_specials":"summer + winter value; pair with Wadi Rum + Dead Sea + Amman","event_peaks":"spring + autumn peak; Petra by Night on select nights","campaign_start":"sell spring/autumn 2-4 mo out; lead EN + GCC (Saudi #1 source) + DE/FR"},"jewels":[{"name":"Petra by Night by candlelight","si_tag":"culture","status":"live","tier":"essential","price_band":"separate ticket","timing":"Mar-Apr & Oct-Nov","commission_path":"DMC/guide","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the Siq lit by 1,500 candles to the Treasury — separate ticket, capacity-limited","si":"culture","blurb":"the Siq lit by 1,500 candles to the Treasury — separate ticket, capacity-limited","when":"Mar-Apr & Oct-Nov","commission":"DMC/guide"},{"name":"A Nabataean archaeology day with a licensed guide","si_tag":"deepdive","status":"live","tier":"essential","price_band":"within the tour","timing":"year-round","commission_path":"DMC 10-15%","draw_rank":1,"timing_type":"ALWAYS-ON","hook":"the Siq, Treasury, Royal Tombs, Colonnaded Street, and the water-engineering story most visitors miss","si":"deepdive","blurb":"the Siq, Treasury, Royal Tombs, Colonnaded Street, and the water-engineering story most visitors miss","when":"year-round","commission":"DMC 10-15%"},{"name":"The climb to the Monastery (Ad-Deir)","si_tag":"hiking","status":"live","tier":"essential","price_band":"within the visit","timing":"Mar-Nov, early","commission_path":"DMC/guide","draw_rank":2,"hook":"~800 rock-cut steps to Petra''s largest monument, above the crowds","si":"hiking","blurb":"~800 rock-cut steps to Petra''s largest monument, above the crowds","when":"Mar-Nov, early","commission":"DMC/guide"},{"name":"A luxury Petra-adjacent lodge + private-guide days","si_tag":"ultra","status":"future","tier":"ultra","price_band":"on application","timing":"Mar-Nov","commission_path":"consortia/DMC","draw_rank":1,"si":"ultra","when":"Mar-Nov","commission":"consortia/DMC"}],"faq":[{"q":"Is it safe to visit Petra right now?","a":"Jordan is US Level 3 - Reconsider Travel, escalated in March 2026 over regional tensions, and we disclose that plainly. The Level-4 Do-Not-Travel zones are the Syria and Iraq border strips in the north and east - Petra sits in the south, far from them. Tour operators resumed Petra, Wadi Rum and Dead Sea programs through 2026. Check the current advisory at book time; we surface it, we don''t bury it.","source":"travel.state.gov","si_tag":"safety"},{"q":"What is Petra?","a":"A 2,000-year-old Nabataean city carved into rose-red sandstone - the Siq gorge, the Treasury (Al-Khazneh), the Monastery, and Petra by Night by candlelight. UNESCO World Heritage since 1985 and one of the New7Wonders of the World.","source":"new7wonders.com","si_tag":"culture"},{"q":"When is the best time to visit Petra?","a":"March-April and October-November - clear light on the sandstone and comfortable days. Summer reaches about 40C (tour early morning); winter is cold with rain and occasional snow.","source":"responsibletravel.com","si_tag":"culture"},{"q":"What does the Jordan Pass cover?","a":"It bundles Petra entry (1-3 days by tier), 40+ sites including Wadi Rum entry and Jerash, and waives the tourist-visa fee if you stay at least 3 nights. Buy it online before arrival. It does not cover Petra by Night, jeep tours or overnight camps - those are separate bookings.","source":"jordanpass.org","si_tag":"deepdive"}],"seo":{"meta_title":"Petra Guide: The Treasury, Petra by Night & Safety (2026) - Best Time to Visit","meta_description":"Plan Petra - the rose-red Nabataean city and New7Wonder, the Siq and the Treasury, Petra by Night, the Jordan Pass, best season spring/autumn, with straight Level-3 safety intel.","slug":"petra-jordan","primary_keyword":"Petra Jordan","long_tail":["Petra Treasury","Petra by Night","is Petra safe","Jordan Pass Petra","best time to visit Petra","Monastery Petra hike"],"search_language":"en","local_keywords":["Petra","Wadi Musa","Al-Khazneh","Al-Deir","Nabataean"],"hreflang":["en","ar","de"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-08-03"},"booking":{"bin":"book_with_disclosure","level":"L3","codes":["reconsider-travel","regional-tensions","terrorism"],"consent_flow":true,"book_suppressed":false,"note":"Jordan US Level 3 Reconsider Travel (escalated March 2026, regional US-Iran tensions). Disclose PROMINENTLY; heightened-consent booking. Level-4 Do-Not-Travel areas = Syria + Iraq border strips + Mansheyat al Ghayyath + Ruwayshid - Petra is in the SOUTH, far from them. Operators resumed Petra/Wadi Rum/Dead Sea programs through 2026. Re-verify each cycle (may revert to L2)."},"si_checklist_25":{"run_date":"2026-08-03","hits":3,"misses":18,"disregarded":3,"note":"Icon of Jordan: culture + deepdive (Nabataean archaeology) + hiking (Monastery/High Place trails) live; ultra (luxury Petra) future. hiking may need Sana to confirm the live SI row. sub_region ''Jordan & Petra'' PROPOSED - awaiting Sana nod. US L3 - disclose."},"sis_present":[{"si":"culture","name":"culture","status":"live","note":"Nabataean rock-cut city, UNESCO 1985, New7Wonders 2007, the Siq + Treasury + Monastery","timing":"Mar-Apr & Oct-Nov","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW"},{"si":"deepdive","name":"deepdive","status":"live","note":"Nabataean archaeology + water engineering with licensed guides; Petra by Night","timing":"Mar-Apr & Oct-Nov","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW"},{"si":"hiking","name":"hiking","status":"live","note":"the Monastery (~800 steps), High Place of Sacrifice, back-route trails","timing":"Mar-Apr & Oct-Nov","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW"},{"si":"ultra","name":"ultra","status":"future","note":"luxury Petra-adjacent lodges + private archaeologist guiding","timing":"Mar-Apr & Oct-Nov","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW"}],"ultra":[{"name":"A luxury Petra-adjacent lodge + private-guide days + a reserved Petra by Night","why